const input = $input.first().json.body;

if (!input || !input.patientTelegramChatId || !input.pickupCode) {
  return [{ json: { skipped: true, reason: 'Missing required fields' } }];
}

const chatId = input.patientTelegramChatId;
const prescriptionId = input.id;
const pickupCode = input.pickupCode;
const token = "8644047281:AAHywXMMM9zpDThyBj_FOgme46RZi_GhzRk";

const text = '\u2705 *Ordonnance prête au retrait* \u2013 N\u00B0 ' + prescriptionId + '\n\n\uD83D\uDCE6 Vos médicaments sont prêts et vous attendent en pharmacie.\n\n\uD83D\uDD11 *Code de retrait :* `' + pickupCode + '`\n\nPrésentez ce code à votre pharmacien pour récupérer vos médicaments.\n\n\u23F1\uFE0F Nous vous recommandez de venir retirer votre commande dans les plus brefs délais.\n\n\u2014\n_MédiLink Tunisie \u2013 Votre santé, notre priorité._';

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.telegram.org/bot' + token + '/sendMessage',
  headers: { 'Content-Type': 'application/json' },
  body: {
    chat_id: chatId,
    text: text,
    parse_mode: 'Markdown'
  }
});

return [{ json: { success: true, chatId, prescriptionId, messageId: response.result.message_id } }];
